from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
import re

_DATE_RE = re.compile(r'^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
_CONVENTIONS = ("30/360_US", "30E/360", "ACT/365F", "ACT/ACT_ISDA")


def _parse_date(value):
    if not isinstance(value, str) or not _DATE_RE.match(value):
        raise ValueError('invalid date')
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError('invalid date')


def _validate_convention(value):
    if not isinstance(value, str) or value not in _CONVENTIONS:
        raise ValueError('invalid convention')
    return value


def _is_leap(year):
    return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)


def _is_last_day_feb(d):
    if d.month != 2:
        return False
    return d.day == (29 if _is_leap(d.year) else 28)


def _unrounded_fraction(start_date, end_date, convention):
    with localcontext() as ctx:
        ctx.prec = 50
        if start_date == end_date:
            return Decimal(0)
        if convention == "ACT/365F":
            actual = (end_date - start_date).days
            return Decimal(actual) / Decimal(365)
        if convention == "ACT/ACT_ISDA":
            total = Decimal(0)
            current = start_date
            while current < end_date:
                if current.year == 9999:
                    segment_end = end_date
                else:
                    next_jan = date(current.year + 1, 1, 1)
                    segment_end = next_jan if next_jan < end_date else end_date
                days_portion = (segment_end - current).days
                denom = Decimal(366) if _is_leap(current.year) else Decimal(365)
                total += Decimal(days_portion) / denom
                current = segment_end
            return total
        if convention == "30/360_US":
            d1 = start_date.day
            d2 = end_date.day
            start_last_feb = _is_last_day_feb(start_date)
            end_last_feb = _is_last_day_feb(end_date)
            if start_last_feb:
                d1 = 30
            if end_last_feb and start_last_feb:
                d2 = 30
            if start_date.day == 31:
                d1 = 30
            if end_date.day == 31 and d1 >= 30:
                d2 = 30
            days = 360 * (end_date.year - start_date.year) + 30 * (end_date.month - start_date.month) + (d2 - d1)
            return Decimal(days) / Decimal(360)
        if convention == "30E/360":
            d1 = min(start_date.day, 30)
            d2 = min(end_date.day, 30)
            days = 360 * (end_date.year - start_date.year) + 30 * (end_date.month - start_date.month) + (d2 - d1)
            return Decimal(days) / Decimal(360)
        raise ValueError('invalid convention')


def _parse_principal(value):
    if not isinstance(value, str):
        raise ValueError('invalid principal')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid principal')
    if not parsed.is_finite() or parsed < 0:
        raise ValueError('invalid principal')
    if parsed.as_tuple().exponent < -2:
        raise ValueError('invalid principal')
    return parsed


def _parse_rate(value):
    if not isinstance(value, str):
        raise ValueError('invalid rate')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid rate')
    if not parsed.is_finite() or parsed < 0 or parsed > 100:
        raise ValueError('invalid rate')
    return parsed


def day_count_fraction(start, end, convention):
    start_date = _parse_date(start)
    end_date = _parse_date(end)
    _validate_convention(convention)
    if end_date < start_date:
        raise ValueError('end before start')
    with localcontext() as ctx:
        ctx.prec = 50
        fraction = _unrounded_fraction(start_date, end_date, convention)
        return fraction.quantize(Decimal('0.0000000000'), rounding=ROUND_HALF_UP)


def accrued_interest(principal, annual_rate_percent, start, end, convention):
    principal_value = _parse_principal(principal)
    rate_value = _parse_rate(annual_rate_percent)
    start_date = _parse_date(start)
    end_date = _parse_date(end)
    _validate_convention(convention)
    if end_date < start_date:
        raise ValueError('end before start')
    with localcontext() as ctx:
        ctx.prec = 50
        fraction = _unrounded_fraction(start_date, end_date, convention)
        result = principal_value * (rate_value / Decimal(100)) * fraction
        return result.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
